import { SEX } from '../config.js';
import {
  addMedication, addNote, addShortTerm, deletePatient, getPatient, listCatalog, listDispenses,
    listNotes, removeMedication, removeNote, removeShortTerm, updatePatient,
    } from '../supabase.js';
    import { openDispenseModal } from '../components/dispense-modal.js';
    import { createMedicationPicker } from '../components/medication-picker.js';
    import { readShortTerm, setShortTermRequired, shortTermFields } from '../components/short-term-fields.js';
    import { ageFrom, fmt, today } from '../lib/date.js';
    import { $, esc, notify, opts, reportError, showLoadError, withBusy } from '../lib/dom.js';
    import { dueInfo, medLine, shortTermActive, shortTermEnd } from '../lib/status.js';

    const kv = (k, v) => `<div><div class="sub" style="margin:0 0 2px">${k}</div><div style="font-weight:600">${v ? esc(v) : '—'}</div></div>`;

    // One patient: personal details, current medication, notes, short-term treatments, history.
    export async function render(view, { params, go }) {
      const id = params[0];
        const s = { patient: null, catalog: {}, notes: [], history: [], picker: null };

          async function load() {
              const [patient, catalog, notes, history] = await Promise.all([getPatient(id), listCatalog(), listNotes(id), listDispenses(id)]);
                  s.patient = patient;
                      s.catalog = catalog;
                          s.notes = notes;
                              s.history = history;
                                }

                                  async function reload() {
                                      try {
                                            await load();
                                                  draw();
                                                      } catch (err) {
                                                            reportError(err);
                                                                }
                                                                  }

                                                                    function medicationSection(p, info) {
                                                                        if (!p.medications.length) return '<p class="sub" style="margin:0">No medication has been dispensed yet.</p>';
                                                                            return `<div class="two" style="margin:0">
                                                                                  <div><div class="sub" style="margin:0 0 2px">${p.medications.length > 1 ? 'Medications' : 'Medication'}</div>
                                                                                          <div style="font-weight:600">${p.medications.map((m) => `<div>${esc(medLine(m))}<span class="sub" style="font-weight:400"> · ${esc(m.dose)}</span>
                                                                                                    <button type="button" class="x" data-del-med="${esc(m.id)}" aria-label="Remove medication" style="color:var(--mut);margin-left:6px">×</button></div>`).join('')}</div></div>
                                                                                                          ${kv('Refill every', p.refill_every + ' days')}${kv('Last given', p.last_given ? fmt(p.last_given) : '')}
                                                                                                                ${kv('Next due', info.nextDue ? fmt(info.nextDue) : '')}${kv('Status', info.label)}
                                                                                                                      ${p.alt_medication ? kv('Alternative given', `${p.alt_medication} (${p.alt_reason})`) : ''}</div>`;
                                                                                                                        }

                                                                                                                          function shortTermSection(p) {
                                                                                                                              const list = p.shortTerm;
                                                                                                                                  return `<div class="box sec"><h3>Short-term treatments</h3>
                                                                                                                                        <p class="sub" style="margin:-6px 0 12px">Other drugs prescribed during a visit, e.g. for malaria, cough, UTI or STI. These are separate from the chronic medication and do not affect refill dates.</p>
                                                                                                                                              <form id="sf">${shortTermFields('st_')}
                                                                                                                                                      <div class="two"><div><label>Date prescribed</label><input name="st_date" type="date" required value="${today()}"></div></div>
                                                                                                                                                              <div class="acts"><button class="btn p sm">Add treatment</button></div></form>
                                                                                                                                                                    ${list.length ? `<div class="tw" style="margin-top:16px"><table style="min-width:640px"><thead><tr><th>Medication</th><th>For</th><th>Prescribed</th><th>Ends</th><th>Status</th><th></th></tr></thead><tbody>
                                                                                                                                                                            ${list.map((t) => `<tr><td>${esc(medLine(t))}<div class="sub">${esc(t.dose)}</div></td><td>${esc(t.condition)}</td><td>${fmt(t.prescribed_on)}</td><td>${fmt(shortTermEnd(t))}</td>
                                                                                                                                                                                      <td>${shortTermActive(t) ? '<span class="pill">Active</span>' : '<span class="sub">Completed</span>'}</td>
                                                                                                                                                                                                <td style="text-align:right"><button type="button" class="x" data-del-st="${esc(t.id)}" aria-label="Remove treatment" style="color:var(--mut)">×</button></td></tr>`).join('')}
                                                                                                                                                                                                        </tbody></table></div>` : ''}</div>`;
                                                                                                                                                                                                          }

                                                                                                                                                                                                            function draw() {
                                                                                                                                                                                                                const p = s.patient;
                                                                                                                                                                                                                    if (!p) {
                                                                                                                                                                                                                          view.innerHTML = `<div class="errbox"><h2>Patient not found</h2><p class="sub">This patient may have been deleted.</p><a class="btn" href="#/patients">← Patients</a></div>`;
                                                                                                                                                                                                                                return;
                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                        const info = dueInfo(p);
                                                                                                                                                                                                                                            const age = ageFrom(p.dob);
                                                                                                                                                                                                                                                view.innerHTML = `
                                                                                                                                                                                                                                                      <div class="top"><a class="btn sm" href="#/patients">← Patients</a>
                                                                                                                                                                                                                                                              <div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn sm" data-edit>Edit details</button><button class="btn p sm" data-dispense>Dispense</button></div></div>
                                                                                                                                                                                                                                                                    <h2 class="title" style="margin-bottom:4px">${esc(p.name)}</h2><div class="sub" style="margin:0 0 20px">${esc(p.pid)}</div>

                                                                                                                                                                                                                                                                          <div class="box sec"><h3>Personal details</h3><div class="two" style="margin:0">
                                                                                                                                                                                                                                                                                  ${kv('Full name', p.name)}${kv('Patient ID', p.pid)}${kv('Date of birth', p.dob ? `${fmt(p.dob)} (${age} yrs)` : '')}
                                                                                                                                                                                                                                                                                          ${kv('Sex', p.sex)}${kv('Phone number', p.phone)}${kv('Address', p.address)}${kv('Condition', p.condition)}</div></div>

                                                                                                                                                                                                                                                                                                <div class="box sec"><h3>Current medication</h3>${medicationSection(p, info)}
                                                                                                                                                                                                                                                                                                        <div style="margin-top:14px" id="medslot"><button type="button" class="btn sm" data-add-med>+ Add medication</button></div></div>

                                                                                                                                                                                                                                                                                                              <div class="box sec"><h3>Pharmacist notes</h3>
                                                                                                                                                                                                                                                                                                                      <form id="nf"><textarea name="t" required rows="3" placeholder="Add a note about this patient, e.g. reacted to Amlodipine, prefers morning collection"></textarea>
                                                                                                                                                                                                                                                                                                                                <div class="acts" style="margin-top:10px"><button class="btn p sm">Add note</button></div></form>
                                                                                                                                                                                                                                                                                                                                        ${s.notes.map((n, i) => `<div style="border-top:1px solid var(--bd2);padding:10px 0;display:flex;justify-content:space-between;gap:10px;margin-top:${i ? 0 : 12}px">
                                                                                                                                                                                                                                                                                                                                                  <div><div class="sub" style="margin:0 0 2px">${fmt(n.created_at)}</div><div style="white-space:pre-wrap">${esc(n.body)}</div></div>
                                                                                                                                                                                                                                                                                                                                                            <button class="x" data-del-note="${esc(n.id)}" aria-label="Delete note" style="color:var(--mut)">×</button></div>`).join('')}</div>

                                                                                                                                                                                                                                                                                                                                                                  ${shortTermSection(p)}

                                                                                                                                                                                                                                                                                                                                                                        <div class="box sec"><h3>Dispense history</h3>${s.history.length
                                                                                                                                                                                                                                                                                                                                                                                ? `<div class="tw"><table style="min-width:420px"><thead><tr><th>Date</th><th>Medication given</th></tr></thead><tbody>
                                                                                                                                                                                                                                                                                                                                                                                          ${s.history.map((h) => `<tr><td>${fmt(h.dispensed_on)}</td><td>${h.alternative ? `${esc(h.alternative)} <span class="sub">(substitute)</span>` : esc(h.medications_given)}</td></tr>`).join('')}</tbody></table></div>`
                                                                                                                                                                                                                                                                                                                                                                                                  : '<p class="sub" style="margin:0">No dispenses recorded.</p>'}</div>

                                                                                                                                                                                                                                                                                                                                                                                                        <div style="text-align:right;margin-top:8px"><button class="btn sm" data-delete style="color:#7a0019">Delete patient</button></div>`;
                                                                                                                                                                                                                                                                                                                                                                                                            setShortTermRequired($('#sf', view), 'st_', true);
                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                // ---- edit-details window ----
                                                                                                                                                                                                                                                                                                                                                                                                                  function openEdit() {
                                                                                                                                                                                                                                                                                                                                                                                                                      const p = s.patient;
                                                                                                                                                                                                                                                                                                                                                                                                                          const overlay = document.createElement('div');
                                                                                                                                                                                                                                                                                                                                                                                                                              overlay.className = 'ov';
                                                                                                                                                                                                                                                                                                                                                                                                                                  overlay.innerHTML = `<div class="box modal" role="dialog" aria-modal="true" aria-label="Edit details">
                                                                                                                                                                                                                                                                                                                                                                                                                                        <div class="mh"><b>Edit details</b><button type="button" class="x" data-close aria-label="Close">×</button></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                              <form class="mb">
                                                                                                                                                                                                                                                                                                                                                                                                                                                      <label>Full name</label><input name="name" required value="${esc(p.name)}">
                                                                                                                                                                                                                                                                                                                                                                                                                                                              <label style="margin-top:12px">Phone number</label><input name="phone" type="tel" value="${esc(p.phone)}">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div class="two" style="margin:12px 0 0"><div><label>Date of birth</label><input name="dob" type="date" required max="${today()}" value="${esc(p.dob || '')}"></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div><label>Sex</label><select name="sex" required><option value="">Select</option>${opts(SEX, p.sex)}</select></div></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <label style="margin-top:12px">Address</label><input name="addr" required value="${esc(p.address)}">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <label style="margin-top:12px">Refill every (days)</label><input name="every" type="number" min="1" required value="${esc(p.refill_every)}">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div class="acts" style="margin-top:20px"><button type="button" class="btn sm" data-close>Cancel</button><button class="btn p sm">Save</button></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </form></div>`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  view.appendChild(overlay);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const close = () => { document.removeEventListener('keydown', onKey); overlay.remove(); };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const onKey = (e) => { if (e.key === 'Escape') close(); };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              document.addEventListener('keydown', onKey);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  overlay.addEventListener('click', (e) => { if (e.target === overlay || e.target.closest('[data-close]')) close(); });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      overlay.querySelector('form').addEventListener('submit', async (e) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            e.preventDefault();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const f = e.target.elements;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const ok = await withBusy(e.submitter, async () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                await updatePatient(id, {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          name: f.name.value.trim(), phone: f.phone.value.trim(), dob: f.dob.value, sex: f.sex.value,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    address: f.addr.value.trim(), refill_every: Number(f.every.value) || p.refill_every,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (ok) { close(); notify('Details saved'); await reload(); }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // ---- clicks ----
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          view.addEventListener('click', async (e) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const t = e.target;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (t.closest('[data-dispense]')) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        openDispenseModal({ host: view, patient: s.patient, catalog: s.catalog, onDone: reload });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } else if (t.closest('[data-edit]')) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  openEdit();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      } else if (t.closest('[data-add-med]')) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            s.picker = createMedicationPicker(s.catalog, s.patient.condition);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const slot = $('#medslot', view);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        slot.innerHTML = '<form id="mf" class="sb" style="margin:0"></form>';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const mf = $('#mf', view);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    mf.appendChild(s.picker.el);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          mf.insertAdjacentHTML('beforeend', '<div class="acts"><button type="button" class="btn sm" data-cancel-med>Cancel</button><button class="btn p sm">Add medication</button></div>');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              } else if (t.closest('[data-cancel-med]')) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    $('#medslot', view).innerHTML = '<button type="button" class="btn sm" data-add-med>+ Add medication</button>';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          s.picker = null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              } else if (t.closest('[data-del-med]')) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (confirm('Remove this medication from the patient?')) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            await withBusy(null, () => removeMedication(t.closest('[data-del-med]').dataset.delMed));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    await reload();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              } else if (t.closest('[data-del-note]')) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (confirm('Delete this note?')) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            await withBusy(null, () => removeNote(t.closest('[data-del-note]').dataset.delNote));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    await reload();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              } else if (t.closest('[data-del-st]')) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (confirm('Remove this short-term treatment?')) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            await withBusy(null, () => removeShortTerm(t.closest('[data-del-st]').dataset.delSt));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    await reload();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              } else if (t.closest('[data-delete]')) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (confirm(`Permanently delete ${s.patient.name} and all their records? This cannot be undone.`)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const ok = await withBusy(t.closest('button'), async () => { await deletePatient(id); return true; });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (ok) { notify('Patient deleted'); go('#/patients'); }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // ---- forms ----
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    view.addEventListener('submit', async (e) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const form = e.target;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (form.id === 'mf') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  e.preventDefault();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const ok = await withBusy(e.submitter, async () => { await addMedication(id, s.picker.read()); return true; });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (ok) { notify('Medication added'); await reload(); }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  } else if (form.id === 'nf') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        e.preventDefault();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const body = form.elements.t.value.trim();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!body) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const ok = await withBusy(e.submitter, async () => { await addNote(id, body); return true; });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (ok) await reload();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    } else if (form.id === 'sf') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          e.preventDefault();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const ok = await withBusy(e.submitter, async () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        await addShortTerm(id, { ...readShortTerm(form, 'st_'), prescribed_on: form.elements.st_date.value });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (ok) { notify('Treatment added'); await reload(); }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        await load();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            draw();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              } catch (err) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  showLoadError(view, err);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    